import{_ as n,o as r,c as a,a3 as t}from"./chunks/framework.z_KJ15Ep.js";const p=JSON.parse('{"title":"Sprachen und Sprachprüfungen auf Zeugnissen abbilden","description":"","frontmatter":{},"headers":[],"relativePath":"zeugnisse/sprachen.md","filePath":"zeugnisse/sprachen.md"}'),i={name:"zeugnisse/sprachen.md"};function s(u,e,h,l,c,d){return r(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="sprachen-und-sprachprufungen-auf-zeugnissen-abbilden" tabindex="-1">Sprachen und Sprachprüfungen auf Zeugnissen abbilden <a class="header-anchor" href="#sprachen-und-sprachprufungen-auf-zeugnissen-abbilden" aria-label="Permalink to &quot;Sprachen und Sprachprüfungen auf Zeugnissen abbilden&quot;">​</a></h1><p>Pflegen Sie Sprachenfolgen und prüfen Sie, welche Art von Sprachprüfung oder Qualifikation vorliegt. Herkunftssprachlicher Unterricht und eine Feststellungsprüfung als Fremdsprachenersatz haben unterschiedliche Folgen für die Zeugnisangaben.</p><h2 id="sprachenfolge-und-referenzniveau-pflegen" tabindex="-1">Sprachenfolge und Referenzniveau pflegen <a class="header-anchor" href="#sprachenfolge-und-referenzniveau-pflegen" aria-label="Permalink to &quot;Sprachenfolge und Referenzniveau pflegen&quot;">​</a></h2><p>Die <a href="/schild3/schueler/laufbahninfo-schueler.html">Laufbahninfo</a> hält die Einträge bereit. Die Anleitung <a href="/schild3/schueler/eingabe-der-ger-niveaus-tutorial.html">GeR-Sprachniveaus erfassen und berechnen</a> beschreibt Einzel- und Gruppenerfassung; Der Gruppenprozess <a href="/zeugnisse/vorbereitung/sprach-referenzniveaus-ermitteln-gruppenprozesse-allgemein.html">Sprachreferenzniveaus aus Leistungsdaten ermitteln</a> übernimmt die Berechnung aus den vorhandenen Daten.</p><p>Bei einem Wechsel nach Klasse 10 ins Gymnasium beachten Sie <a href="/zeugnisse/vorbereitung/sprachenfolge-bei-seiteneinsteigern-des-gymnasiums-in-zeugnissen-korrekt-ausgeben-tutorial.html">Sprachenfolgen bei Seiteneinstieg ins Gymnasium ausgeben</a>. Bereits früher belegte Sprachen und manuell einzutragende Qualifikationen müssen dabei berücksichtigt werden.</p><h2 id="unterricht-und-prufung-unterscheiden" tabindex="-1">Unterricht und Prüfung unterscheiden <a class="header-anchor" href="#unterricht-und-prufung-unterscheiden" aria-label="Permalink to &quot;Unterricht und Prüfung unterscheiden&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Aufgabe</th><th>Anleitung</th></tr></thead><tbody><tr><td>Herkunftssprachlichen Unterricht und Prüfungen abbilden</td><td><a href="/schild3/unterricht-kataloge/herkunftssprachlicher-unterricht-tutorial.html">Herkunftssprachlicher Unterricht</a></td></tr><tr><td>Eine Pflicht- oder Wahlpflichtfremdsprache durch Prüfung ersetzen</td><td><a href="/zeugnisse/sekundarstufen/sprachpruefung-feststellungspruefung-anstelle-von-pflicht-oder-wahlpflichtfremdsprachen-tutorial.html">Sprachfeststellungsprüfung</a></td></tr></tbody></table><p>Prüfen Sie den konkreten Zeugnisfall im jeweiligen Artikel. Die dort beschriebenen Unterschiede dürfen bei Abschluss-, Abgangs- und Abiturzeugnissen nicht gleichgesetzt werden.</p>',8)])])}const g=n(i,[["render",s]]);export{p as __pageData,g as default};
